'use strict';

// MODULES //

var ndarraylike2scalar = require( '@stdlib/ndarray-base-ndarraylike2scalar' );
var numelDimension = require( '@stdlib/ndarray-base-numel-dimension' );
var getStride = require( '@stdlib/ndarray-base-stride' );
var getOffset = require( '@stdlib/ndarray-base-offset' );
var getData = require( '@stdlib/ndarray-base-data-buffer' );
var clipIndex = require( '@stdlib/ndarray-base-clip-index' );
var strided = require( '@stdlib/blas-ext-base-gfill-by' ).ndarray;


// MAIN //

/**
* Fills a one-dimensional ndarray according to a provided callback function.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the starting index (inclusive).
*     -   a zero-dimensional ndarray containing the ending index (exclusive).
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @param {Function} clbk - callback function
* @param {*} [thisArg] - callback execution context
* @returns {ndarray} input ndarray
*
* @example
* var scalar2ndarray = require( '@stdlib/ndarray-from-scalar' );
* var vector = require( '@stdlib/ndarray-vector-ctor' );
*
* function fill() {
*     return 5.0;
* }
*
* var x = vector( [ -2.0, 1.0, 3.0, -5.0, 4.0, -6.0 ], 'generic' );
*
* var start = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var end = scalar2ndarray( 3, {
*     'dtype': 'generic'
* });
*
* var out = gfillBy( [ x, start, end ], fill );
* // returns <ndarray>[ 5.0, 5.0, 5.0, -5.0, 4.0, -6.0 ]
*/
function gfillBy( arrays, clbk, thisArg ) {
	var stride;
	var offset;
	var start;
	var end;
	var N;
	var x;

	x = arrays[ 0 ];

	N = numelDimension( x, 0 );
	start = clipIndex( ndarraylike2scalar( arrays[ 1 ] ), N );
	end = clipIndex( ndarraylike2scalar( arrays[ 2 ] ), N );
	if ( start >= end ) {
		return x;
	}
	stride = getStride( x, 0 );
	offset = getOffset( x ) + ( stride*start );

	strided( end-start, getData( x ), stride, offset, wrapper, null );
	return x;

	/**
	* Invokes a provided callback.
	*
	* @private
	* @param {*} value - current array element
	* @param {NonNegativeInteger} aidx - current array element index
	* @param {NonNegativeInteger} sidx - current strided array element index
	* @param {Collection} arr - input array
	* @returns {*} result
	*/
	function wrapper( value, aidx ) {
		return clbk.call( thisArg, value, aidx + start, x );
	}
}


// EXPORTS //

module.exports = gfillBy;
